;(function(){
  function hcdwClickFix(){
    var icon=document.getElementById('iwAuthor');
    if(!icon) return;
    icon.style.setProperty('z-index','2147483647','important');
    icon.style.setProperty('pointer-events','auto','important');
    icon.style.setProperty('cursor','pointer','important');
    if(icon.getAttribute('data-hcdw-click')==='1') return;
    icon.setAttribute('data-hcdw-click','1');
    icon.addEventListener('click',function(e){
      try{
        e.stopImmediatePropagation(); e.preventDefault();
        var url='https://iirose.com/#u/5f0265d667635';
        var w=null;
        try{w=window.open(url,'_blank');}catch(err){}
        if(!w){
          var a=document.createElement('a');
          a.href=url; a.target='_blank'; a.rel='noopener';
          document.body.appendChild(a); a.click();
          setTimeout(function(){try{document.body.removeChild(a);}catch(err){}},50);
        }
      }catch(err){console.error('[hcdw666]',err);}
    },true);
    var hd=document.querySelector('.iw-hd');
    if(hd && hd.getAttribute('data-hcdw-hd')!=='1'){
      hd.setAttribute('data-hcdw-hd','1');
      hd.addEventListener('click',function(e){
        try{
          var t=e.target;
          if(t && (t.id==='iwReset' || (t.className&&String(t.className).indexOf('iw-swap')>=0))) return;
          e.stopImmediatePropagation();
          var wrap=document.querySelector('.iw-wrap');
          if(wrap){
            var cls=wrap.classList;
            if(cls.contains('iw-min')){cls.remove('iw-min');}else{cls.add('iw-min');}
          }
        }catch(err){console.error('[hcdw666]',err);}
      },true);
    }
  }
  hcdwClickFix();
  setInterval(hcdwClickFix,2000);
})();

;(function(){
  function hcdwLogUi(){
    var wrap=document.querySelector('.iw-wrap');
    if(!wrap) return;
    var hd=wrap.querySelector('.iw-hd')||wrap;
    var btn=document.getElementById('iwLogBtn');
    if(!btn){
      btn=document.createElement('div');
      btn.id='iwLogBtn';
      btn.textContent='日志';
      btn.style.cssText='position:absolute;right:4px;top:2px;font-size:10px;color:#ffd76a;cursor:pointer;z-index:999999;background:rgba(0,0,0,0.35);padding:1px 6px;border-radius:3px;border:1px solid rgba(255,215,106,0.5)';
      hd.appendChild(btn);
      btn.addEventListener('click',function(e){
        try{
          e.stopImmediatePropagation(); e.preventDefault();
          var box=document.getElementById('iwLogBox');
          if(box){ if(box.style.display==='none'){box.style.display='block';} else {box.style.display='none';} }
        }catch(err){}
      },true);
      var box=document.createElement('div');
      box.id='iwLogBox';
      box.style.cssText='display:none;position:absolute;right:0;left:0;bottom:0;max-height:110px;overflow:auto;background:rgba(0,0,0,0.82);color:#8fe08f;font-size:9px;line-height:1.4;padding:4px 6px;z-index:999998;font-family:monospace;word-break:break-all;border-top:1px solid rgba(255,255,255,0.15)';
      wrap.appendChild(box);
    }
    var box=document.getElementById('iwLogBox');
    if(!box) return;
    var logs=window.__hcdwLogs||[];
    var last=box.getAttribute('data-len')||'0';
    if(String(logs.length)!==last){
      box.setAttribute('data-len',String(logs.length));
      if(box.style.display!=='none'){
        var html='';
        for(var i=Math.max(0,logs.length-40);i<logs.length;i++){ html+='<div>'+String(logs[i]).replace(/</g,'&lt;')+'</div>'; }
        box.innerHTML=html;
        box.scrollTop=box.scrollHeight;
      }
    }
  }
  hcdwLogUi();
  setInterval(hcdwLogUi,1500);
})();
